// VALIDATE & ANONYMISE
// Accepts webhook JSON (camelCase) or form fields (labels), checks inputs,
// and removes the candidate's name, email and phone before the CV goes to the AI.
const incoming = $input.first().json;
const body = incoming.body ?? incoming;

const pick = (...keys) => {
  for (const k of keys) {
    if (body[k] !== undefined && body[k] !== null) return String(body[k]).trim();
  }
  return "";
};

const candidateName = pick("candidateName", "Candidate Name");
const email = pick("email", "Email");
const jobTitle = pick("jobTitle", "Job Title");
const cvText = pick("cvText", "CV Text");
const jobDescription = pick("jobDescription", "Job Description");

const errors = [];
if (!cvText) errors.push("CV text is missing.");
else if (cvText.length < 50) errors.push("CV text is too short to screen (under 50 characters).");
else if (cvText.length > 30000) errors.push("CV text is too long (over 30,000 characters).");

if (!jobDescription) errors.push("Job description is missing.");
else if (jobDescription.length < 30) errors.push("Job description is too short to screen against (under 30 characters).");
else if (jobDescription.length > 15000) errors.push("Job description is too long (over 15,000 characters).");

if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push("Email address does not look valid.");

// Fairness safeguard: hide identity details from the AI.
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
// Contact details first, then the name (so emails are not broken apart).
let redactedCv = cvText
  .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, "[EMAIL]")
  .replace(/https?:\/\/\S+|(?:www\.)?linkedin\.com\/\S+/gi, "[LINK]")
  .replace(/\+?\d[\d\s().-]{7,}\d/g, (m) => ((m.match(/\d/g) || []).length >= 10 ? "[PHONE]" : m));
const nameParts = candidateName
  ? [candidateName, ...candidateName.split(/\s+/).filter((p) => p.length > 2)]
  : [];
for (const part of nameParts) {
  redactedCv = redactedCv.replace(new RegExp(`\\b${escapeRe(part)}\\b`, "gi"), "[CANDIDATE]");
}

return [{
  json: {
    ok: errors.length === 0,
    errorType: errors.length ? "input" : null,
    errors,
    candidateName,
    email,
    jobTitle,
    jobDescription,
    cvText,
    redactedCv,
    receivedAt: new Date().toISOString()
  }
}];

// PARSE & SCORE
// 1) Reads the AI's JSON answer safely.
// 2) Checks every evidence quote really exists in the CV (hallucination check).
// 3) Calculates the match score with a fixed rubric, in code, so results are consistent.
const input = $('Validate Inputs').first().json;
const resp = $input.first().json;
const MODEL = "openai/gpt-oss-20b";

const fail = (errorType, errors, extra = {}) => [{
  json: {
    ok: false, errorType, errors,
    candidateName: input.candidateName, jobTitle: input.jobTitle, ...extra
  }
}];

// --- 1. Parse the AI answer ---------------------------------------------
if (resp.error) {
  const msg = typeof resp.error === "string" ? resp.error : (resp.error.message || JSON.stringify(resp.error));
  return fail("ai_service", [`The AI service did not respond successfully after retries: ${String(msg).slice(0, 300)}`]);
}
const raw = resp?.choices?.[0]?.message?.content ?? "";
let data;
try {
  data = JSON.parse(String(raw).replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, ""));
} catch (e) {
  return fail("ai_format", ["The AI answer was not valid JSON, so it could not be scored."], { rawResponse: String(raw).slice(0, 1500) });
}
if (!Array.isArray(data.required_skills) || data.required_skills.length === 0) {
  return fail("ai_format", ["The AI answer did not list any required skills, so it could not be scored."], { rawResponse: String(raw).slice(0, 1500) });
}
// Never score an incomplete answer – a missing section would silently lower the score.
const missing = ["preferred_skills", "experience", "education", "strengths", "gaps", "interview_questions", "summary"]
  .filter((k) => data[k] === undefined || data[k] === null);
if (missing.length) {
  return fail("ai_format", [`The AI answer was incomplete (missing: ${missing.join(", ")}), so it was not scored. Please try again.`], { rawResponse: String(raw).slice(0, 1500) });
}

// --- 2. Evidence verification -------------------------------------------
const norm = (s) => String(s || "")
  .toLowerCase()
  .replace(/[‘’“”"'`]/g, "")
  .replace(/[‐-―]/g, "-")
  .replace(/[^a-z0-9+#.\-\[\] ]+/g, " ")
  .replace(/\s+/g, " ")
  .trim();
const cvNorm = norm(input.redactedCv);
const cvWords = new Set(cvNorm.split(" "));

function isVerified(quote) {
  const q = norm(quote);
  if (!q) return false;
  if (cvNorm.includes(q)) return true;
  // Allow small differences: at least 85% of the quote's meaningful words appear in the CV.
  const words = q.split(" ").filter((w) => w.length > 2);
  if (words.length < 3) return false;
  const found = words.filter((w) => cvWords.has(w)).length;
  return found / words.length >= 0.85;
}

const STATUSES = ["met", "partial", "not_evidenced", "lacks"];
const BASE_CREDIT = { met: 1, partial: 0.5, not_evidenced: 0, lacks: 0 };
const unverified = [];

function checkSkills(list, group) {
  return (Array.isArray(list) ? list : []).map((s) => {
    let status = STATUSES.includes(s.status) ? s.status : "not_evidenced";
    const evidence = String(s.evidence || "").trim();
    let verified = null;
    let credit = BASE_CREDIT[status];
    if (status === "met" || status === "partial") {
      verified = isVerified(evidence);
      if (!verified) {
        credit = credit / 2; // halve credit when the quote cannot be found in the CV
        unverified.push(`${group}: "${s.skill}" (quote not found in CV)`);
      }
    }
    return { skill: String(s.skill || "").trim(), status, evidence, evidenceVerified: verified, note: String(s.note || "").trim(), credit };
  });
}

const required = checkSkills(data.required_skills, "Required skill");
const preferred = checkSkills(data.preferred_skills, "Preferred skill");

const exp = data.experience || {};
const EXP_CREDIT = { strong: 1, relevant: 0.7, limited: 0.35, none: 0 };
const expRelevance = Object.keys(EXP_CREDIT).includes(exp.relevance) ? exp.relevance : "none";
const expEvidence = (Array.isArray(exp.evidence) ? exp.evidence : [exp.evidence]).filter(Boolean).map(String);
const expVerified = expEvidence.length ? expEvidence.every(isVerified) : expRelevance === "none";
let expCredit = EXP_CREDIT[expRelevance];
if (!expVerified && expCredit > 0) { expCredit /= 2; unverified.push("Experience: supporting quote not found in CV"); }

const edu = data.education || {};
const EDU_CREDIT = { meets: 1, partial: 0.5, not_evidenced: 0 };
const eduStatus = ["meets", "partial", "not_evidenced", "not_required"].includes(edu.status) ? edu.status : "not_evidenced";
let eduCredit = eduStatus === "not_required" ? null : EDU_CREDIT[eduStatus];
const eduVerified = eduStatus === "meets" || eduStatus === "partial" ? isVerified(edu.evidence) : null;
if (eduVerified === false) { eduCredit /= 2; unverified.push("Education: quote not found in CV"); }

// --- 3. Rubric score (calculated in code) --------------------------------
const avg = (arr) => (arr.length ? arr.reduce((a, s) => a + s.credit, 0) / arr.length : null);
const components = [
  { name: "Required skills", weight: 50, value: avg(required) },
  { name: "Preferred skills", weight: 20, value: avg(preferred) },
  { name: "Relevant experience", weight: 20, value: expCredit },
  { name: "Education", weight: 10, value: eduCredit }
].filter((c) => c.value !== null);

const totalWeight = components.reduce((a, c) => a + c.weight, 0);
const score = Math.round(components.reduce((a, c) => a + c.weight * c.value, 0) / totalWeight * 100);
const breakdown = components.map((c) => ({
  component: c.name,
  weight: Math.round((c.weight / totalWeight) * 100),
  achievedPercent: Math.round(c.value * 100),
  points: Math.round((c.weight * c.value / totalWeight) * 100 * 10) / 10
}));

const requiredGaps = required.filter((s) => s.status === "not_evidenced" || s.status === "lacks");
const requiredLacks = required.filter((s) => s.status === "lacks");
let band;
if (score >= 75 && requiredGaps.length === 0) band = "Strong match";
else if (score >= 50 && requiredLacks.length === 0) band = "Possible match";
else band = "Weak match";

const allChecked = [...required, ...preferred].filter((s) => s.evidenceVerified !== null);
const verifiedShare = allChecked.length ? allChecked.filter((s) => s.evidenceVerified).length / allChecked.length : 1;

const flags = [];
if (unverified.length) flags.push(...unverified.map((u) => `Unverified evidence – ${u}`));
if (requiredLacks.length) flags.push(`CV indicates the candidate lacks: ${requiredLacks.map((s) => s.skill).join(", ")}`);
if (required.length < 2) flags.push("Only one required skill was identified – check the job description is detailed enough.");

return [{
  json: {
    ok: true,
    candidateName: input.candidateName,
    jobTitle: input.jobTitle,
    score,
    band,
    breakdown,
    evidenceVerifiedPercent: Math.round(verifiedShare * 100),
    requiredSkills: required,
    preferredSkills: preferred,
    experience: {
      relevance: expRelevance,
      relevantYearsEstimate: typeof exp.relevant_years_estimate === "number" ? exp.relevant_years_estimate : null,
      evidence: expEvidence,
      evidenceVerified: expVerified,
      summary: String(exp.summary || "")
    },
    education: { status: eduStatus, evidence: String(edu.evidence || ""), evidenceVerified: eduVerified, note: String(edu.note || "") },
    strengths: (Array.isArray(data.strengths) ? data.strengths : []).map((s) => ({ point: String(s.point || s), evidence: String(s.evidence || ""), evidenceVerified: s.evidence ? isVerified(s.evidence) : null })),
    gaps: (Array.isArray(data.gaps) ? data.gaps : []).map((g) => ({ point: String(g.point || g), type: ["partial", "lacks"].includes(g.type) ? g.type : "not_evidenced" })),
    interviewQuestions: (Array.isArray(data.interview_questions) ? data.interview_questions : []).map(String).filter(Boolean),
    summary: String(data.summary || ""),
    flags,
    meta: {
      model: MODEL,
      scoringRubric: "Required skills 50%, preferred skills 20%, relevant experience 20%, education 10% (re-weighted if a part does not apply). Met = full credit, partial = half, not evidenced / lacks = none; credit is halved when the AI's quote cannot be found in the CV.",
      bands: "Strong ≥75 with all required skills at least partly evidenced; Possible ≥50 with no required skill explicitly lacking; otherwise Weak.",
      anonymised: true,
      screenedAt: new Date().toISOString(),
      disclaimer: "AI-assisted screening to support human review. Not a hiring decision."
    }
  }
}];

// BUILD REPORT (form version)
// The form's end page removes inline styles, so this builds clean HTML
// and the look comes from the "Show Report" node's Custom Form Styling.
// Produces: `response` (structured JSON), `statusCode`, and `html` (for the report page).
const r = $input.first().json;
const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

// ---------- Error case ----------
if (!r.ok) {
  const statusCode = r.errorType === "input" ? 400 : 502;
  const title = r.errorType === "input" ? "⚠️ Please check the submission" : "⚠️ Screening could not be completed";
  const html =
    `<h2>${title}</h2>` +
    `<ul>${(r.errors || []).map((e) => `<li>${esc(e)}</li>`).join("")}</ul>` +
    `<p><em>Nothing was saved. Go back, fix the details above and submit again.</em></p>`;
  return [{ json: { ok: false, statusCode, html, response: { ok: false, errorType: r.errorType, errors: r.errors || [] } } }];
}

// ---------- Success case ----------
const STATUS = { met: "✅ Met", partial: "🟡 Partly met", not_evidenced: "⚪ Not evidenced", lacks: "❌ Lacks (per CV)" };
const BAND = { "Strong match": "🟢 Strong match", "Possible match": "🟡 Possible match", "Weak match": "🔴 Weak match" };

const skillTable = (rows) => rows.length
  ? `<table><tr><th>Requirement</th><th>Status</th><th>Evidence from CV</th></tr>` +
    rows.map((s) =>
      `<tr><td>${esc(s.skill)}</td><td><strong>${STATUS[s.status]}</strong></td>` +
      `<td>${s.evidence ? `“${esc(s.evidence)}”` : "—"}` +
      `${s.evidenceVerified === false ? " <strong>(quote not found in CV – half credit)</strong>" : ""}` +
      `${s.note ? `<br><em>${esc(s.note)}</em>` : ""}</td></tr>`
    ).join("") + `</table>`
  : `<p><em>None listed in the job description.</em></p>`;

const list = (items) => (items.length ? `<ul>${items.join("")}</ul>` : `<p><em>None.</em></p>`);

const html =
  `<h2>${esc(r.candidateName || "Candidate")} · ${esc(r.jobTitle)}</h2>` +
  `<h1>${r.score}/100 · ${BAND[r.band]}</h1>` +
  `<p>${esc(r.summary)}</p>` +
  `<p><small>🔍 Evidence verified against the CV: ${r.evidenceVerifiedPercent}% · 🛡️ Candidate details hidden from the AI</small></p>` +

  `<h3>📊 Score breakdown</h3>` +
  `<table><tr><th>Part</th><th>Weight</th><th>Achieved</th><th>Points</th></tr>` +
  r.breakdown.map((b) => `<tr><td>${b.component}</td><td>${b.weight}%</td><td>${b.achievedPercent}%</td><td>${b.points}</td></tr>`).join("") +
  `</table>` +

  `<h3>🎯 Required skills</h3>` + skillTable(r.requiredSkills) +
  `<h3>⭐ Preferred skills</h3>` + skillTable(r.preferredSkills) +

  `<h3>💼 Relevant experience</h3>` +
  `<p><strong>${esc(r.experience.relevance)}</strong>` +
  `${r.experience.relevantYearsEstimate !== null ? ` · about ${r.experience.relevantYearsEstimate} year(s)` : ""}</p>` +
  (r.experience.summary ? `<p>${esc(r.experience.summary)}</p>` : "") +
  list(r.experience.evidence.map((e) => `<li>“${esc(e)}”</li>`)) +

  `<h3>🎓 Education</h3>` +
  `<p><strong>${esc(r.education.status.replace("_", " "))}</strong>` +
  `${r.education.evidence ? ` – “${esc(r.education.evidence)}”` : ""}</p>` +

  `<h3>💪 Strengths</h3>` +
  list(r.strengths.map((s) => `<li>${esc(s.point)}${s.evidence ? ` – <em>“${esc(s.evidence)}”</em>` : ""}</li>`)) +

  `<h3>🧩 Gaps and missing evidence</h3>` +
  list(r.gaps.map((g) => `<li>${esc(g.point)} <em>(${g.type === "lacks" ? "CV shows it is lacking" : g.type === "partial" ? "only partly shown in CV" : "not mentioned in CV"})</em></li>`)) +

  `<h3>💬 Suggested interview questions</h3>` +
  (r.interviewQuestions.length ? `<ol>${r.interviewQuestions.map((q) => `<li>${esc(q)}</li>`).join("")}</ol>` : "<p><em>None.</em></p>") +

  (r.flags.length ? `<h3>⚠️ Points for the reviewer to check</h3>` + list(r.flags.map((f) => `<li>${esc(f)}</li>`)) : "") +

  `<hr>` +
  `<p><small><strong>How the score works:</strong> ${esc(r.meta.scoringRubric)} ${esc(r.meta.bands)}</small></p>` +
  `<p><small>${esc(r.meta.disclaimer)}</small></p>`;

const { ok, ...rest } = r;
return [{ json: { ok: true, statusCode: 200, html, response: { ok: true, ...rest } } }];

// PREPARE RECORD
// Turns a successful screening into one row for the "CV Screenings" data table,
// including the submitted CV text (applicants are told on the form that it is stored).
const r = $input.first().json.response;
const input = $('Validate Inputs').first().json;
const met = r.requiredSkills.filter((s) => s.status === "met").length;

return [{
  json: {
    candidate_name: r.candidateName,
    email: input.email,
    job_title: r.jobTitle,
    score: r.score,
    band: r.band,
    evidence_verified_pct: r.evidenceVerifiedPercent,
    required_met: `${met}/${r.requiredSkills.length}`,
    gaps: r.gaps.map((g) => g.point).join("; ").slice(0, 1000),
    summary: r.summary.slice(0, 1000),
    cv_text: input.cvText
  }
}];

