.header th, .header td { padding: 9px 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #f4f4f5; }
.header tr:last-child td { border-bottom: none; }
.header td strong { white-space: nowrap; color: #0a0a0a; }
.header tr:hover td { background: #fafafa; }
.header > ul, .header > ol { text-align: left; padding-left: 20px; margin: 6px 0 12px; }
.header li { margin: 4px 0; }
.header li::marker { color: #4f46e5; }
.header > hr { border: none; border-top: 1px solid #f0f0f0; margin: 22px 0; }
